#!/usr/bin/env node

import { mkdir, readdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const projectRoot = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  "..",
);
const bitsRoot = path.join(projectRoot, "bits");
const generatedJsonPath = path.join(
  projectRoot,
  "src",
  "catalog",
  "inventory.generated.json",
);
const generatedTsPath = path.join(
  projectRoot,
  "src",
  "catalog",
  "inventory.generated.ts",
);

const GENERATED_BANNER = [
  "/* eslint-disable */",
  "// This file is generated by scripts/generate-inventory.mjs.",
  "// Do not edit it manually.",
  "",
].join("\n");

const normalizePath = (value) => value.split(path.sep).join("/");

const kebabToPascal = (value) =>
  value
    .split("-")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("");

const listBitJsonFiles = async (dirPath) => {
  const entries = await readdir(dirPath, { withFileTypes: true });
  const files = await Promise.all(
    entries.map(async (entry) => {
      const fullPath = path.join(dirPath, entry.name);
      if (entry.isDirectory()) {
        return listBitJsonFiles(fullPath);
      }
      if (entry.isFile() && entry.name === "bit.json") {
        return [fullPath];
      }
      return [];
    }),
  );
  return files.flat().sort((left, right) => left.localeCompare(right));
};

const assertManifest = (manifest, relativePath) => {
  if (!manifest || typeof manifest !== "object" || Array.isArray(manifest)) {
    throw new Error(`bit.json must be an object: ${relativePath}`);
  }
  if (typeof manifest.name !== "string" || manifest.name.trim().length === 0) {
    throw new Error(
      `bit.json name must be a non-empty string: ${relativePath}`,
    );
  }
  if (
    typeof manifest.title !== "string" ||
    manifest.title.trim().length === 0
  ) {
    throw new Error(
      `bit.json title must be a non-empty string: ${relativePath}`,
    );
  }
  if (
    typeof manifest.description !== "string" ||
    manifest.description.trim().length === 0
  ) {
    throw new Error(
      `bit.json description must be a non-empty string: ${relativePath}`,
    );
  }
  if (
    !Array.isArray(manifest.tags) ||
    manifest.tags.some((tag) => typeof tag !== "string")
  ) {
    throw new Error(`bit.json tags must be a string array: ${relativePath}`);
  }
  if (
    typeof manifest.duration !== "number" ||
    !Number.isFinite(manifest.duration)
  ) {
    throw new Error(`bit.json duration must be a number: ${relativePath}`);
  }
  if (!Array.isArray(manifest.helpers)) {
    throw new Error(`bit.json helpers must be an array: ${relativePath}`);
  }
  if (!manifest.registryItem || typeof manifest.registryItem !== "object") {
    throw new Error(`bit.json registryItem is required: ${relativePath}`);
  }
};

const toInventoryEntry = (bitJsonPath, manifest, sourceCode) => {
  const sourcePath = normalizePath(
    path.relative(
      projectRoot,
      path.join(path.dirname(bitJsonPath), "index.html"),
    ),
  );
  const helpers = [...manifest.helpers];

  return {
    exportName: kebabToPascal(manifest.name),
    id: manifest.name,
    name: manifest.title,
    description: manifest.description,
    tags: [...manifest.tags],
    duration: manifest.duration,
    width: manifest.width,
    height: manifest.height,
    sourcePath,
    componentNames: [...helpers],
    registryDependencies: [...helpers],
    helpers,
    sourceCode,
    registry: manifest.registryItem,
  };
};

const assertUniqueEntries = (entries) => {
  const seenIds = new Map();
  const seenExports = new Map();
  const seenSourcePaths = new Set();

  for (const entry of entries) {
    const existingIdPath = seenIds.get(entry.id);
    if (existingIdPath) {
      throw new Error(
        `Duplicate bit id "${entry.id}" in ${existingIdPath} and ${entry.sourcePath}`,
      );
    }

    const existingExportPath = seenExports.get(entry.exportName);
    if (existingExportPath) {
      throw new Error(
        `Duplicate exportName "${entry.exportName}" in ${existingExportPath} and ${entry.sourcePath}`,
      );
    }

    if (seenSourcePaths.has(entry.sourcePath)) {
      throw new Error(
        `Duplicate sourcePath "${entry.sourcePath}" in generated inventory.`,
      );
    }

    seenIds.set(entry.id, entry.sourcePath);
    seenExports.set(entry.exportName, entry.sourcePath);
    seenSourcePaths.add(entry.sourcePath);
  }
};

const renderInventoryModule = (entries) =>
  [
    GENERATED_BANNER,
    'import type { SharedBitInventoryEntry } from "./contracts";',
    "",
    `export const sharedBitInventory: SharedBitInventoryEntry[] = ${JSON.stringify(entries, null, 2)};`,
    "",
    "export const sharedBitInventoryCount = sharedBitInventory.length;",
    "",
  ].join("\n");

export const generateBitInventory = async () => {
  const bitFiles = await listBitJsonFiles(bitsRoot);
  const entries = [];

  for (const bitJsonPath of bitFiles) {
    const relativePath = normalizePath(path.relative(projectRoot, bitJsonPath));
    const manifest = JSON.parse(await readFile(bitJsonPath, "utf8"));
    assertManifest(manifest, relativePath);

    const htmlPath = path.join(path.dirname(bitJsonPath), "index.html");
    const sourceCode = await readFile(htmlPath, "utf8");
    if (!sourceCode.includes("data-composition-id")) {
      throw new Error(
        `Bit HTML is missing data-composition-id: ${relativePath}`,
      );
    }

    entries.push(toInventoryEntry(bitJsonPath, manifest, sourceCode));
  }

  assertUniqueEntries(entries);

  await mkdir(path.dirname(generatedTsPath), { recursive: true });
  await writeFile(generatedTsPath, renderInventoryModule(entries));
  await writeFile(generatedJsonPath, `${JSON.stringify(entries, null, 2)}\n`);

  return entries;
};

const main = async () => {
  const entries = await generateBitInventory();
  console.log(`Generated bit inventory with ${entries.length} bit(s).`);
};

if (
  process.argv[1] &&
  fileURLToPath(import.meta.url) === path.resolve(process.argv[1])
) {
  main().catch((error) => {
    console.error(error instanceof Error ? error.message : String(error));
    process.exit(1);
  });
}
